import React, { useEffect, useState } from 'react';
import axios from 'axios';

const Gallery = () => {
  const [images, setImages] = useState([]);
  const [image, setImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [likeStatus, setLikeStatus] = useState({});
  const [comments, setComments] = useState({});
  const [modalImage, setModalImage] = useState(null);

  useEffect(() => {
    fetchImages();
  }, []);

  const fetchImages = async () => {
    setLoading(true);
    try {
      const { data } = await axios.get('/api/gallery');
      setImages(data);
      const initialLikes = data.reduce((acc, img) => {
        acc[img._id] = img.likes || 0;
        return acc;
      }, {});
      setLikeStatus(initialLikes);

      const initialComments = data.reduce((acc, img) => {
        acc[img._id] = img.comments || [];
        return acc;
      }, {});
      setComments(initialComments);
    } catch (error) {
      console.error('Error fetching images:', error);
    } finally {
      setLoading(false);
    }
  };

  // ✅ Upload Image (Admin Only)
  const uploadImage = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('image', image);

    try {
      const config = {
        headers: {
          'Content-Type': 'multipart/form-data',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
      };

      await axios.post('/api/gallery', formData, config);
      alert('Image uploaded successfully');
      fetchImages(); // Refresh after upload
    } catch (error) {
      alert('Failed to upload image');
    }
  };

  // ✅ Delete Image (Admin Only)
  const deleteImage = async (id) => {
    if (window.confirm('Are you sure you want to delete this image?')) {
      try {
        const config = {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`,
          },
        };
        await axios.delete(`/api/gallery/${id}`, config);
        alert('Image deleted successfully');
        fetchImages(); // Refresh after delete
      } catch (error) {
        alert('Failed to delete image');
      }
    }
  };

  // ✅ Like Image
  const likeImage = async (id) => {
    try {
      const { data } = await axios.post(`/api/gallery/${id}/like`);
      setLikeStatus((prev) => ({ ...prev, [id]: data.likes }));
    } catch (error) {
      console.error('Failed to like image:', error);
    }
  };

  // ✅ Add Comment
  const addComment = async (id, comment) => {
    try {
      const { data } = await axios.post(`/api/gallery/${id}/comment`, { comment });
      setComments((prev) => ({
        ...prev,
        [id]: data.comments,
      }));
    } catch (error) {
      console.error('Failed to add comment:', error);
    }
  };

  return (
    <div className="container mt-4">
      <h2 className="mb-4">Event Gallery</h2>

      {/* ✅ Image Upload Form (Admin Only) */}
      {localStorage.getItem('isAdmin') === 'true' && (
        <form onSubmit={uploadImage} className="mb-4">
          <div className="mb-3">
            <input
              type="file"
              className="form-control"
              onChange={(e) => setImage(e.target.files[0])}
              required
            />
          </div>
          <button type="submit" className="btn btn-primary">
            Upload Image
          </button>
        </form>
      )}

      {/* ✅ Display Images */}
      <div className="row">
        {loading ? (
          <p>Loading images...</p>
        ) : (
          images.map((img) => (
            <div key={img._id} className="col-md-3 mb-3">
              <img
                src={img.imageUrl}
                alt="Event"
                className="img-fluid rounded"
                style={{ height: '200px', objectFit: 'cover', cursor: 'pointer' }}
                onClick={() => setModalImage(img.imageUrl)} // Open modal on click
              />

              {/* ✅ Like Button */}
              <div className="mt-2">
                <button
                  className="btn btn-outline-primary btn-sm me-2"
                  onClick={() => likeImage(img._id)}
                >
                  ❤️ Like ({likeStatus[img._id]})
                </button>

                {/* ✅ Delete Button (Admin Only) */}
                {localStorage.getItem('isAdmin') === 'true' && (
                  <button
                    className="btn btn-outline-danger btn-sm"
                    onClick={() => deleteImage(img._id)}
                  >
                    🗑️ Delete
                  </button>
                )}
              </div>

              {/* ✅ Comments Section */}
              <div className="mt-3">
                {comments[img._id]?.map((cmt, index) => (
                  <div key={index} className="bg-light p-1 rounded mb-1">
                    {cmt}
                  </div>
                ))}

                <form
                  onSubmit={(e) => {
                    e.preventDefault();
                    const comment = e.target.elements.comment.value;
                    if (comment.trim()) {
                      addComment(img._id, comment);
                      e.target.reset();
                    }
                  }}
                  className="mt-2"
                >
                  <input
                    type="text"
                    name="comment"
                    className="form-control"
                    placeholder="Add a comment..."
                    required
                  />
                </form>
              </div>
            </div>
          ))
        )}
      </div>

      {/* ✅ Lightbox/Modal */}
      {modalImage && (
        <div
          className="modal fade show"
          style={{ display: 'block', backgroundColor: 'rgba(0, 0, 0, 0.7)' }}
          onClick={() => setModalImage(null)}
        >
          <div className="modal-dialog">
            <div className="modal-content">
              <img
                src={modalImage}
                alt="Preview"
                className="img-fluid rounded"
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Gallery;
